      "label": "Grieving baker",
      "want": "the matriarch's grave protected"
    },
    {
      "id": "c72",
      "label": "Desperate merchant",
      "want": "the elven relics buried with the matriarch"
    },
    {
      "id": "p2",
      "label": "Conflicted trapper",
      "want": "to live unmolested by either side"
    }
