      "opens": "Why does a human merchant from the south covet an elven grave?"
    },
    {
      "n": 2,
      "type": "talk",
      "title": "The Trapper at Stonegill",
      "job": "Find the trapper at Stonegill and convince him to break his silence",
      "people": [
        "p2"
      ],
      "trouble": {
        "who": "the trapper, armed and paid for his quiet",
        "carry": "a bow and a purse of the merchant's coin",
        "will": "refuse to speak and try to slip away"
      },
      "win": "The trapper confesses: the merchant c72 hired him to watch the grave; c72 believes the matriarch's burial gifts hold a cure for his cursed daughter",
      "opens": "Can the company reach c72 before he escapes with the grave's treasure?"
    },
    {
      "n": 3,
      "type": "escort",
      "title": "The Merchant's Flight",
      "job": "Escort Lariane through the forest to Woldshaw where c72 has made camp",
      "people": [
        "p1"
      ],
      "trouble": {
        "who": "the merchant's hired guards defending the camp",
        "carry": "swords, bows, and torches",
        "will": "ambush the company and try to turn them back"
      },
      "win": "The guards are scattered; Lariane and the company reach Woldshaw safely and face c72 in his camp",
      "opens": "Will the merchant yield, flee, or make his stand?"
    }
  ],
  "showdown": {
    "title": "The Merchant and the Matriarch",
    "job": "Confront c72 and force him to answer for the desecration of the grave",
    "people": [
      "c72"
    ],
    "trouble": {
      "who": "the merchant c72, proud and driven by love",
      "carry": "a blade, a purse of gold, and a bone charm his daughter made",
      "will": "try to bargain, fight, or flee rather than yield empty-handed"
    },
    "settles": "Lariane's matriarch is laid to rest in peace and her grave is sealed; the elven home is safe from plunder.",
    "lose": "the matriarch's grave forever desecrated, and Lariane's home given over to a merchant's theft"
  },
  "options": [
    {
      "way": "gold",
      "label": "Take the merchant's treasure and cast him out penniless"
    },
    {
      "way": "captive",
      "label": "Chain him in your cells to face the elves' judgment"
    },
    {
      "way": "recruit",
      "label": "Offer him a path: join the company and earn back what he has lost"
    }
  ],
  "pitch": "The elven matriarch's funeral song rings through the Western Forests, answered from the burial grove. Lariane, baker and witness, comes to you desperate: someone is opening the grave. By dawn, the tomb robbers will strip the gifts and vanish. You reach Harrowford at night. Torchlight flickers from fresh earth. Men with iron hooks turn at the sound of your approach. One of them clutches something old and golden—a bone charm of the dead."
}
```

